import type { SxProps, Theme } from '@mui/material/styles';

/** Display face for public marketing pages; body copy stays on DM Sans. */
export const MARKETING_DISPLAY_FONT =
  '"Plus Jakarta Sans", "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif';

export type MarketingHeadingLevel = 'display' | 'h1' | 'h2' | 'h3';

const baseHeading = {
  fontFamily: MARKETING_DISPLAY_FONT,
  letterSpacing: '-0.03em',
  color: 'text.primary',
} as const;

export const marketingHeadingStyles: Record<MarketingHeadingLevel, SxProps<Theme>> = {
  display: {
    ...baseHeading,
    fontWeight: 800,
    lineHeight: 1.1,
    fontSize: { xs: '2.125rem', sm: '2.5rem', md: '3rem' },
    letterSpacing: '-0.04em',
  },
  h1: {
    ...baseHeading,
    fontWeight: 800,
    lineHeight: 1.15,
    fontSize: { xs: '1.875rem', sm: '2.125rem', md: '2.375rem' },
    letterSpacing: '-0.035em',
  },
  h2: {
    ...baseHeading,
    fontWeight: 700,
    lineHeight: 1.2,
    fontSize: { xs: '1.5rem', sm: '1.625rem', md: '1.875rem' },
    letterSpacing: '-0.03em',
  },
  h3: {
    ...baseHeading,
    fontWeight: 700,
    lineHeight: 1.25,
    fontSize: { xs: '1.125rem', sm: '1.25rem', md: '1.375rem' },
    letterSpacing: '-0.02em',
  },
};

export const marketingSubheadingSx: SxProps<Theme> = {
  fontFamily: MARKETING_DISPLAY_FONT,
  fontWeight: 600,
  letterSpacing: '-0.01em',
  lineHeight: 1.5,
};

export const marketingGradientTextSx = (theme: Theme): SxProps<Theme> => ({
  backgroundImage: `linear-gradient(135deg, ${theme.palette.primary.dark} 0%, ${theme.palette.primary.main} 52%, ${theme.palette.secondary.main} 100%)`,
  WebkitBackgroundClip: 'text',
  WebkitTextFillColor: 'transparent',
  backgroundClip: 'text',
});
