import React, { useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Typography,
} from '@mui/material';
import { ExpandMore as ExpandMoreIcon } from '@mui/icons-material';
import useAppTranslation from '../../hooks/useAppTranslation';

export interface DashboardSetupFocusSectionProps {
  children: React.ReactNode;
  defaultExpanded?: boolean;
  /** When provided, section is controlled — use to gate advanced API queries. */
  expanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
}

/**
 * Collapses advanced dashboard panels so first-time users see a shorter home screen.
 * Children unmount when collapsed to avoid fetching ISO/advisory/peer data until demanded.
 */
export const DashboardSetupFocusSection: React.FC<DashboardSetupFocusSectionProps> = ({
  children,
  defaultExpanded = false,
  expanded: controlledExpanded,
  onExpandedChange,
}) => {
  const [uncontrolledExpanded, setUncontrolledExpanded] = useState(defaultExpanded);
  const { t } = useAppTranslation();
  const expanded = controlledExpanded ?? uncontrolledExpanded;

  return (
    <Accordion
      expanded={expanded}
      onChange={(_, isExpanded) => {
        if (controlledExpanded === undefined) {
          setUncontrolledExpanded(isExpanded);
        }
        onExpandedChange?.(isExpanded);
      }}
      variant="outlined"
      sx={{ mb: 3 }}
      TransitionProps={{ unmountOnExit: true }}
    >
      <AccordionSummary expandIcon={<ExpandMoreIcon />} aria-controls="dashboard-advanced-content">
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
            {t('dashboard.setupFocusTitle')}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {t('dashboard.setupFocusSubtitle')}
          </Typography>
        </Box>
      </AccordionSummary>
      <AccordionDetails sx={{ pt: 0 }}>{children}</AccordionDetails>
    </Accordion>
  );
};

export default DashboardSetupFocusSection;
