import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import {
  ArrowForward as ArrowForwardIcon,
  Factory as FactoryIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import useAppTranslation from '../../hooks/useAppTranslation';

export interface DashboardOperationsPromptProps {
  visible: boolean;
}

export const DashboardOperationsPrompt: React.FC<DashboardOperationsPromptProps> = ({ visible }) => {
  const navigate = useNavigate();
  const { t } = useAppTranslation();

  if (!visible) {
    return null;
  }

  return (
    <Card
      variant="outlined"
      sx={{
        mb: 3,
        borderColor: 'info.main',
        bgcolor: (theme) =>
          theme.palette.mode === 'dark' ? 'rgba(2, 136, 209, 0.12)' : 'rgba(2, 136, 209, 0.04)',
      }}
    >
      <CardContent>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
          <FactoryIcon color="info" sx={{ fontSize: 32 }} />
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
              {t('dashboard.operationsPromptTitle')}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.55 }}>
              Unlock operations quests: add electricity and fuel, name your plant, and save a live picture.
              Full Scope 1–3 detail stays optional under Operations.
            </Typography>
            <Chip size="small" label="~5 min" variant="outlined" sx={{ mt: 1 }} />
          </Box>
          <Button
            variant="contained"
            color="info"
            endIcon={<ArrowForwardIcon />}
            onClick={() => navigate('/operations')}
            sx={{ flexShrink: 0 }}
          >
            Play ops quests
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default DashboardOperationsPrompt;
